class LargestTemperatureChange {
  public int solve(int[] arr, int k) {
    int l = 0, r = 0;
    MaxMinQueue maxMinQueue = new MaxMinQueue();
    int res = Integer.MIN_VALUE;
    while (r < arr.length) {
      maxMinQueue.push(arr[r]);
      r++;
      if (r - l == k) {
        res = Math.max(res, maxMinQueue.max() - maxMinQueue.min());
        maxMinQueue.pop();
        l++;
      }
    }
    return res;
  }
